        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        if u == n-1:
            return d
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return -1 if dist[n-1] == float('inf') else dist[n-1] if n > 0 else -1"}
